// The versus channel — one pipe shared by every competitive stack game (Tetris,
// Puyo, Panel de Pon): event → attack units → OFFSET against the target's own
// incoming queue → deliver the remainder. Different games plug different unit
// maths and different receivers; the pipe is built once.

export interface VersusConfig<R, S> {
  /** How many attack units a resolved move sends. */
  attack: (result: R) => number;
  /** Materialise `units` of garbage on a board; returns the steps/journal it made. */
  receive: (board: unknown, units: number) => S;
  /** Cap on units delivered in one drop (Puyo's 5-row rock cap). Default Infinity. */
  maxPerDelivery?: number;
  /** `hold` keeps queued garbage until the sender stops clearing (Fever); `immediate`
   * drops it as soon as their chain ends (Tsu). Default `immediate`. */
  timing?: 'immediate' | 'hold';
}

export interface Duel<R, S> {
  /** Register a player's board handle. */
  addPlayer(id: string, board: unknown): void;
  /** A player resolved a move: compute attack, offset it against their OWN pending
   * incoming first, send the remainder to the opponent(s). Returns units sent. */
  send(id: string, result: R): number;
  /** Units currently queued to land on a player (the incoming meter for the HUD). */
  pending(id: string): number;
  /** Materialise the queued garbage on a player's board (call when it's safe). */
  deliver(id: string): S | null;
}

/** Create a 1-v-1 (or N-way) versus channel. Opponent = every other registered id. */
export function createVersus<R, S>(cfg: VersusConfig<R, S>): Duel<R, S> {
  const boards = new Map<string, unknown>();
  const incoming = new Map<string, number>();
  const cap = cfg.maxPerDelivery ?? Infinity;

  return {
    addPlayer(id, board) { boards.set(id, board); incoming.set(id, 0); },

    send(id, result) {
      let units = Math.max(0, Math.floor(cfg.attack(result)));
      // Offset: cancel this player's OWN pending incoming first.
      const mine = incoming.get(id) ?? 0;
      if (mine > 0 && units > 0) {
        const cancel = Math.min(mine, units);
        incoming.set(id, mine - cancel);
        units -= cancel;
      }
      if (units <= 0) return 0;
      // Deliver the remainder to the opponents.
      for (const other of boards.keys()) {
        if (other === id) continue;
        incoming.set(other, (incoming.get(other) ?? 0) + units);
      }
      return units;
    },

    pending(id) { return incoming.get(id) ?? 0; },

    deliver(id) {
      const units = Math.min(incoming.get(id) ?? 0, cap);
      if (units <= 0) return null;
      incoming.set(id, (incoming.get(id) ?? 0) - units);
      return cfg.receive(boards.get(id), units);
    },
  };
}
