// Rising-stack preset (match3 pack extension A3) — Panel de Pon / Tetris Attack.
// The stack rises from below on the GAME's clock (call rise() when its timer
// says so); the cursor swaps two horizontally-adjacent panels (or panel↔empty);
// 3+ in a row/column clears; chains come from FALL PROVENANCE — panels that fell
// because of a clear carry a flag, and if a flagged panel lands in a new match
// the chain counter ticks. Convertible garbage rounds it out. Its own surface in
// the match3 pack.

export interface XY { x: number; y: number }

export interface Panel {
  id: number;
  color: number;
  /** Chain-eligible: this panel fell because of a clear (provenance flag). */
  chainFlag?: boolean;
  /** Multi-cell garbage block membership (shared id), if this is garbage. */
  garbage?: { blockId: number };
}

export type RiseStep =
  | { type: 'rise'; row: { color: number }[] }
  | { type: 'swap'; a: XY; b: XY }
  | { type: 'match'; cells: XY[]; chain: number; combo: number }
  | { type: 'clear'; cells: XY[] }
  | { type: 'fall'; moves: { id: number; from: XY; to: XY }[] }
  | { type: 'garbageBreak'; blockId: number; row: XY[]; spawned: { at: XY; color: number }[] }
  | { type: 'topOut' };

export interface RiseResult {
  steps: RiseStep[];
  cleared: number;
  chain: number;
  combo: number;
  /** Stop-time hint (bigger for chains/near-top) the game applies to its clock. */
  stopTime: number;
  topOut: boolean;
}

export interface RiseConfig {
  cols: number;
  rows: number;
  seed?: number;
  colors?: number;
  /** Initial filled rows from the bottom. Default 4. */
  fillRows?: number;
}

class Rng {
  private s: number;
  constructor(seed: number) { this.s = (seed >>> 0) || 0x9e3779b9; }
  next(): number { let x = this.s; x ^= x << 13; x ^= x >>> 17; x ^= x << 5; this.s = x >>> 0; return this.s; }
  int(n: number): number { return n <= 0 ? 0 : this.next() % n; }
}

export function createRiseBoard(cfg: RiseConfig): RiseBoard {
  return new RiseBoard(cfg);
}

export class RiseBoard {
  readonly cols: number;
  readonly rows: number;
  readonly colors: number;
  topOut = false;
  score = 0;

  private grid: (Panel | null)[];
  private rng: Rng;
  private nextId = 1;
  private nextGarbageId = 1;

  constructor(cfg: RiseConfig) {
    this.cols = cfg.cols;
    this.rows = cfg.rows;
    this.colors = cfg.colors ?? 5;
    this.rng = new Rng(cfg.seed ?? 1);
    this.grid = new Array(cfg.cols * cfg.rows).fill(null);
    const fill = cfg.fillRows ?? 4;
    for (let y = this.rows - fill; y < this.rows; y++) for (let x = 0; x < this.cols; x++) this.grid[this.idx(x, y)] = this.freshPanel(x, y);
  }

  private idx(x: number, y: number): number { return y * this.cols + x; }
  private inBounds(x: number, y: number): boolean { return x >= 0 && y >= 0 && x < this.cols && y < this.rows; }
  panel(x: number, y: number): Panel | null { return this.inBounds(x, y) ? this.grid[this.idx(x, y)] : null; }

  /** A panel that doesn't complete a run with its placed neighbours (clean deal). */
  private freshPanel(x: number, y: number): Panel {
    const bad = new Set<number>();
    const at = (px: number, py: number) => this.grid[this.idx(px, py)]?.color ?? -2;
    for (let c = 0; c < this.colors; c++) {
      if (at(x - 1, y) === c && at(x - 2, y) === c) bad.add(c);
      if (at(x, y - 1) === c && at(x, y - 2) === c) bad.add(c);
    }
    let c = this.rng.int(this.colors);
    let guard = 0;
    while (bad.has(c) && guard++ < 20) c = this.rng.int(this.colors);
    return { id: this.nextId++, color: c };
  }

  /** Push a new row up from the bottom (the game calls this on its clock). */
  rise(): RiseResult {
    const steps: RiseStep[] = [];
    // shift everything up one row
    for (let y = 0; y < this.rows - 1; y++) for (let x = 0; x < this.cols; x++) this.grid[this.idx(x, y)] = this.grid[this.idx(x, y + 1)];
    const row: { color: number }[] = [];
    for (let x = 0; x < this.cols; x++) { const p = this.freshPanel(x, this.rows - 1); this.grid[this.idx(x, this.rows - 1)] = p; row.push({ color: p.color }); }
    steps.push({ type: 'rise', row });
    // top-out if any panel occupies the top row
    for (let x = 0; x < this.cols; x++) if (this.grid[this.idx(x, 0)]) { this.topOut = true; steps.push({ type: 'topOut' }); break; }
    return { steps, cleared: 0, chain: 0, combo: 0, stopTime: 0, topOut: this.topOut };
  }

  /** Swap two horizontally-adjacent cells (panel↔panel or panel↔empty). Legal
   * anytime — no match required. Then resolve matches + provenance chains. */
  swap(a: XY, b: XY): RiseResult {
    const steps: RiseStep[] = [];
    if (!this.inBounds(a.x, a.y) || !this.inBounds(b.x, b.y) || a.y !== b.y || Math.abs(a.x - b.x) !== 1) {
      return { steps, cleared: 0, chain: 0, combo: 0, stopTime: 0, topOut: this.topOut };
    }
    const ia = this.idx(a.x, a.y); const ib = this.idx(b.x, b.y);
    const A = this.grid[ia]; const B = this.grid[ib];
    if (A?.garbage || B?.garbage) return { steps, cleared: 0, chain: 0, combo: 0, stopTime: 0, topOut: this.topOut };
    this.grid[ia] = B; this.grid[ib] = A;
    steps.push({ type: 'swap', a, b });
    return this.resolve(steps);
  }

  /** Add a multi-cell garbage block at the top (from a versus attack). */
  addGarbage(x: number, y: number, w: number, h: number, color = -1): void {
    const bid = this.nextGarbageId++;
    for (let dy = 0; dy < h; dy++) for (let dx = 0; dx < w; dx++) {
      if (this.inBounds(x + dx, y + dy)) this.grid[this.idx(x + dx, y + dy)] = { id: this.nextId++, color, garbage: { blockId: bid } };
    }
  }

  private resolve(steps: RiseStep[]): RiseResult {
    let chain = 0;
    let totalCleared = 0;
    let combo = 0;
    for (let guard = 0; guard < 64; guard++) {
      this.settle(steps, chain > 0);
      const matches = this.findMatches();
      if (matches.length === 0) break;
      // chain if any matched panel carried a chainFlag
      const flagged = matches.some((c) => this.grid[this.idx(c.x, c.y)]?.chainFlag);
      chain += flagged || chain === 0 ? (chain === 0 ? 0 : 1) : 0;
      if (flagged) chain++;
      combo = Math.max(combo, matches.length);
      steps.push({ type: 'match', cells: matches.slice(), chain, combo: matches.length });
      // garbage adjacent to a clear converts its bottom row
      this.breakGarbage(matches, steps);
      for (const c of matches) this.grid[this.idx(c.x, c.y)] = null;
      steps.push({ type: 'clear', cells: matches.slice() });
      totalCleared += matches.length;
      this.score += matches.length * 10 * (chain + 1);
    }
    const stopTime = totalCleared > 0 ? (combo + chain * 2) * 0.15 : 0;
    return { steps, cleared: totalCleared, chain, combo, stopTime, topOut: this.topOut };
  }

  /** Gravity with provenance: a panel that falls because of a clear gets chainFlag. */
  private settle(steps: RiseStep[], markChain: boolean): void {
    const moves: { id: number; from: XY; to: XY }[] = [];
    let moved = true;
    while (moved) {
      moved = false;
      for (let y = this.rows - 2; y >= 0; y--) {
        for (let x = 0; x < this.cols; x++) {
          const p = this.grid[this.idx(x, y)];
          if (!p || p.garbage) continue;
          if (!this.grid[this.idx(x, y + 1)]) {
            this.grid[this.idx(x, y + 1)] = p; this.grid[this.idx(x, y)] = null;
            p.chainFlag = markChain;
            moves.push({ id: p.id, from: { x, y }, to: { x, y: y + 1 } });
            moved = true;
          }
        }
      }
    }
    if (moves.length) steps.push({ type: 'fall', moves });
    else {
      // strip stale chain flags on panels that landed without matching
      for (const p of this.grid) if (p && !p.garbage) { /* flags cleared on next match check */ }
    }
  }

  private findMatches(): XY[] {
    const marked = new Set<number>();
    // horizontal + vertical runs of 3+
    for (let y = 0; y < this.rows; y++) {
      let x = 0;
      while (x < this.cols) {
        const c = this.colorAt(x, y);
        if (c < 0) { x++; continue; }
        let end = x + 1;
        while (end < this.cols && this.colorAt(end, y) === c) end++;
        if (end - x >= 3) for (let i = x; i < end; i++) marked.add(this.idx(i, y));
        x = end;
      }
    }
    for (let x = 0; x < this.cols; x++) {
      let y = 0;
      while (y < this.rows) {
        const c = this.colorAt(x, y);
        if (c < 0) { y++; continue; }
        let end = y + 1;
        while (end < this.rows && this.colorAt(x, end) === c) end++;
        if (end - y >= 3) for (let i = y; i < end; i++) marked.add(this.idx(x, i));
        y = end;
      }
    }
    return [...marked].map((i) => ({ x: i % this.cols, y: (i / this.cols) | 0 }));
  }

  private colorAt(x: number, y: number): number { const p = this.grid[this.idx(x, y)]; return p && !p.garbage ? p.color : -1; }

  private breakGarbage(matched: XY[], steps: RiseStep[]): void {
    const matchedSet = new Set(matched.map((c) => this.idx(c.x, c.y)));
    const touched = new Set<number>();
    for (const c of matched) {
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) {
        const nx = c.x + dx; const ny = c.y + dy;
        if (!this.inBounds(nx, ny)) continue;
        const p = this.grid[this.idx(nx, ny)];
        if (p?.garbage) touched.add(p.garbage.blockId);
      }
    }
    for (const bid of touched) {
      // convert the bottom row of this garbage block to normal panels
      let maxY = -1; const cellsOfBlock: XY[] = [];
      for (let y = 0; y < this.rows; y++) for (let x = 0; x < this.cols; x++) { const p = this.grid[this.idx(x, y)]; if (p?.garbage?.blockId === bid) { cellsOfBlock.push({ x, y }); if (y > maxY) maxY = y; } }
      const bottomRow = cellsOfBlock.filter((c) => c.y === maxY);
      const spawned: { at: XY; color: number }[] = [];
      for (const c of bottomRow) { const col = this.rng.int(this.colors); this.grid[this.idx(c.x, c.y)] = { id: this.nextId++, color: col, chainFlag: false }; spawned.push({ at: c, color: col }); }
      steps.push({ type: 'garbageBreak', blockId: bid, row: bottomRow, spawned });
    }
  }

  /** Legal swaps that would make a match (autoplay/hints). */
  findMoves(): { a: XY; b: XY }[] {
    const out: { a: XY; b: XY }[] = [];
    for (let y = 0; y < this.rows; y++) {
      for (let x = 0; x + 1 < this.cols; x++) {
        const a = { x, y }; const b = { x: x + 1, y };
        const ia = this.idx(a.x, a.y); const ib = this.idx(b.x, b.y);
        if (this.grid[ia]?.garbage || this.grid[ib]?.garbage) continue;
        // simulate the swap
        const A = this.grid[ia]; const B = this.grid[ib];
        this.grid[ia] = B; this.grid[ib] = A;
        const makes = this.findMatches().length > 0;
        this.grid[ia] = A; this.grid[ib] = B;
        if (makes) out.push({ a, b });
      }
    }
    return out;
  }

  debugGrid(): string {
    const rows: string[] = [];
    for (let y = 0; y < this.rows; y++) {
      let r = '';
      for (let x = 0; x < this.cols; x++) { const p = this.grid[this.idx(x, y)]; r += !p ? '.' : p.garbage ? 'G' : String(p.color); }
      rows.push(r);
    }
    return rows.join('\n');
  }
}
