// Triple-Town-style placement merging (match3 pack extension A2). No gravity, no
// refill: each turn you place the dealt item; 3+ orthogonally-connected identical
// items merge into the next tier AT the placement cell and cascade. Adds mobile
// hostiles ("bears") you kill by enclosure, and generators. Its own surface in
// the match3 pack — shares the pack's doctrine (instant logic + event journal).

export interface XY { x: number; y: number }

/** A placed item: a tier in a named chain, or a special kind. */
export interface Item {
  id: number;
  /** Chain colour/type; items merge only with equal (type, tier). */
  type: number;
  tier: number;
  kind?: 'walker' | 'tombstone' | 'generator' | 'block';
  /** Generator: remaining charges. */
  charges?: number;
}

export type PlaceStep =
  | { type: 'place'; at: XY; item: Item }
  | { type: 'merge'; at: XY; from: XY[]; result: Item }
  | { type: 'walk'; moves: { id: number; from: XY; to: XY }[] }
  | { type: 'tombstone'; cells: XY[] }
  | { type: 'generatorSpawn'; from: XY; at: XY; item: Item }
  | { type: 'gameOver' };

export interface PlaceResult {
  valid: boolean;
  steps: PlaceStep[];
  merges: number;
  topTier: number;
  gameOver: boolean;
}

export interface PlaceMergeConfig {
  cols: number;
  rows: number;
  seed?: number;
  maxTier?: number;
  /** Weighted deal table: [type, tier, weight]. Default: mostly tier-0 grass. */
  deal?: [number, number, number][];
  /** Chance per turn a walker spawns from the deal instead. Default 0.08. */
  walkerChance?: number;
}

class Rng {
  private s: number;
  constructor(seed: number) { this.s = (seed >>> 0) || 0x9e3779b9; }
  next(): number { let x = this.s; x ^= x << 13; x ^= x >>> 17; x ^= x << 5; this.s = x >>> 0; return this.s; }
  int(n: number): number { return n <= 0 ? 0 : this.next() % n; }
  float(): number { return this.next() / 0x100000000; }
  weighted(w: number[]): number { let t = 0; for (const v of w) t += Math.max(0, v); if (t <= 0) return this.int(w.length); let r = this.float() * t; for (let i = 0; i < w.length; i++) { r -= Math.max(0, w[i]); if (r < 0) return i; } return w.length - 1; }
}

export function createPlaceMerge(cfg: PlaceMergeConfig): PlaceMerge {
  return new PlaceMerge(cfg);
}

export class PlaceMerge {
  readonly cols: number;
  readonly rows: number;
  readonly maxTier: number;
  gameOver = false;
  score = 0;
  turns = 0;

  private grid: (Item | null)[];
  private rng: Rng;
  private nextId = 1;
  private cfg: PlaceMergeConfig;
  private dealItem: Item;
  private stored: Item | null = null;

  constructor(cfg: PlaceMergeConfig) {
    this.cfg = cfg;
    this.cols = cfg.cols;
    this.rows = cfg.rows;
    this.maxTier = cfg.maxTier ?? 6;
    this.rng = new Rng(cfg.seed ?? 1);
    this.grid = new Array(cfg.cols * cfg.rows).fill(null);
    this.dealItem = this.roll();
  }

  private idx(x: number, y: number): number { return y * this.cols + x; }
  private inBounds(x: number, y: number): boolean { return x >= 0 && y >= 0 && x < this.cols && y < this.rows; }
  item(x: number, y: number): Item | null { return this.inBounds(x, y) ? this.grid[this.idx(x, y)] : null; }
  /** The item about to be placed. */
  get deal(): Item { return this.dealItem; }
  get storage(): Item | null { return this.stored; }

  private roll(): Item {
    if (this.rng.float() < (this.cfg.walkerChance ?? 0.08)) return { id: this.nextId++, type: -1, tier: 0, kind: 'walker' };
    const table = this.cfg.deal ?? [[0, 0, 70], [1, 0, 20], [2, 0, 8], [0, 0, 2]];
    const pick = table[this.rng.weighted(table.map((t) => t[2]))];
    return { id: this.nextId++, type: pick[0], tier: pick[1], kind: 'block' };
  }

  private neighbours(x: number, y: number): XY[] {
    const out: XY[] = [];
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) if (this.inBounds(x + dx, y + dy)) out.push({ x: x + dx, y: y + dy });
    return out;
  }

  private group(x: number, y: number, type: number, tier: number): XY[] {
    const out: XY[] = [];
    const seen = new Set<number>([this.idx(x, y)]);
    const stack: XY[] = [{ x, y }];
    while (stack.length) {
      const p = stack.pop()!;
      out.push(p);
      for (const nb of this.neighbours(p.x, p.y)) {
        const it = this.grid[this.idx(nb.x, nb.y)];
        const i = this.idx(nb.x, nb.y);
        if (seen.has(i) || !it || it.kind !== 'block' || it.type !== type || it.tier !== tier) continue;
        seen.add(i); stack.push(nb);
      }
    }
    return out;
  }

  /** Place the current deal at an empty cell. Resolves merges, runs the turn. */
  place(at: XY): PlaceResult {
    const steps: PlaceStep[] = [];
    if (this.gameOver || !this.inBounds(at.x, at.y) || this.grid[this.idx(at.x, at.y)]) {
      return { valid: false, steps, merges: 0, topTier: this.topTier(), gameOver: this.gameOver };
    }
    const placed = this.dealItem;
    this.grid[this.idx(at.x, at.y)] = placed;
    steps.push({ type: 'place', at, item: placed });
    this.turns++;

    let merges = 0;
    if (placed.kind === 'block') merges = this.resolveMerges(at, steps);

    // Turn systems: walkers move; enclosed walker-groups die → tombstones.
    this.moveWalkers(steps);

    this.dealItem = this.stored ? this.takeStored() : this.roll();
    if (!this.anyEmpty()) { this.gameOver = true; steps.push({ type: 'gameOver' }); }
    return { valid: true, steps, merges, topTier: this.topTier(), gameOver: this.gameOver };
  }

  /** Stow the deal in the one storage slot (swaps with a stored item). */
  store(): void {
    if (this.gameOver) return;
    const tmp = this.stored;
    this.stored = this.dealItem;
    this.dealItem = tmp ?? this.roll();
  }
  private takeStored(): Item { const s = this.stored!; this.stored = null; return s; }

  private resolveMerges(at: XY, steps: PlaceStep[]): number {
    let pivot = at;
    let count = 0;
    for (let guard = 0; guard < 64; guard++) {
      const it = this.grid[this.idx(pivot.x, pivot.y)];
      if (!it || it.kind !== 'block' || it.tier >= this.maxTier) break;
      const grp = this.group(pivot.x, pivot.y, it.type, it.tier);
      if (grp.length < 3) break;
      // remove all, spawn next tier at the pivot
      for (const c of grp) this.grid[this.idx(c.x, c.y)] = null;
      const bonus = grp.length >= 4 ? 1 : 0; // over-merge = a fancier result (+points)
      const result: Item = { id: this.nextId++, type: it.type, tier: it.tier + 1, kind: 'block' };
      this.grid[this.idx(pivot.x, pivot.y)] = result;
      steps.push({ type: 'merge', at: pivot, from: grp.filter((c) => !(c.x === pivot.x && c.y === pivot.y)), result });
      this.score += (result.tier + 1) * 10 * (1 + bonus);
      count++;
      // cascade from the same pivot (the new tier may complete another group)
    }
    return count;
  }

  private moveWalkers(steps: PlaceStep[]): void {
    const walkers: XY[] = [];
    for (let y = 0; y < this.rows; y++) for (let x = 0; x < this.cols; x++) if (this.grid[this.idx(x, y)]?.kind === 'walker') walkers.push({ x, y });
    const moves: { id: number; from: XY; to: XY }[] = [];
    const tombstones: XY[] = [];
    for (const w of walkers) {
      const it = this.grid[this.idx(w.x, w.y)];
      if (!it) continue;
      const empties = this.neighbours(w.x, w.y).filter((nb) => !this.grid[this.idx(nb.x, nb.y)]);
      if (empties.length === 0) {
        // enclosed → dies, becomes a tombstone (which merges via its own chain)
        this.grid[this.idx(w.x, w.y)] = { id: it.id, type: 100, tier: 0, kind: 'block' };
        tombstones.push(w);
      } else {
        const to = empties[this.rng.int(empties.length)];
        this.grid[this.idx(to.x, to.y)] = it;
        this.grid[this.idx(w.x, w.y)] = null;
        moves.push({ id: it.id, from: w, to });
      }
    }
    if (moves.length) steps.push({ type: 'walk', moves });
    if (tombstones.length) steps.push({ type: 'tombstone', cells: tombstones });
  }

  private anyEmpty(): boolean { return this.grid.some((c) => c === null); }
  private topTier(): number { let t = 0; for (const c of this.grid) if (c && c.tier > t) t = c.tier; return t; }

  /** Legal placements (every empty cell), best first by predicted merge size. */
  findPlaces(): { at: XY; merges: number }[] {
    const out: { at: XY; merges: number }[] = [];
    const it = this.dealItem;
    for (let y = 0; y < this.rows; y++) for (let x = 0; x < this.cols; x++) {
      if (this.grid[this.idx(x, y)]) continue;
      let m = 0;
      if (it.kind === 'block') {
        // simulate: would placing here reach a group of 3?
        this.grid[this.idx(x, y)] = it;
        m = this.group(x, y, it.type, it.tier).length;
        this.grid[this.idx(x, y)] = null;
      }
      out.push({ at: { x, y }, merges: m });
    }
    return out.sort((a, b) => b.merges - a.merges);
  }

  /** Auto-play: always place where it merges most (else an open cell). */
  autoplay(maxTurns = 500): PlaceResult[] {
    const out: PlaceResult[] = [];
    for (let n = 0; n < maxTurns && !this.gameOver; n++) {
      const best = this.findPlaces()[0];
      if (!best) break;
      out.push(this.place(best.at));
    }
    return out;
  }

  debugGrid(): string {
    const rows: string[] = [];
    for (let y = 0; y < this.rows; y++) {
      let r = '';
      for (let x = 0; x < this.cols; x++) { const it = this.grid[this.idx(x, y)]; r += !it ? '.' : it.kind === 'walker' ? 'B' : String(it.tier); }
      rows.push(r);
    }
    return rows.join('\n');
  }
}
